'use strict';
// Draft generated by FreeLLMAPI (dots-3-note-preview); reviewed by Claude.
const bcrypt = require('bcryptjs');
const crypto = require('crypto');
const { pool, withTransaction } = require('../config/db');
const AppError = require('../utils/AppError');
const { revokeEverywhere } = require('./authService');

const BCRYPT_COST = 12;

/** Re-checks the user's password before any sensitive account change. */
async function verifyPassword(userId, password) {
  const { rows } = await pool.query('SELECT password_hash FROM users WHERE id = $1', [userId]);
  if (!rows[0] || !(await bcrypt.compare(password, rows[0].password_hash))) {
    throw new AppError(401, 'Current password is incorrect', 'INVALID_CREDENTIALS');
  }
}

/** Active sessions = refresh-token families that still have a usable token. */
async function listSessions(userId, currentRefreshToken) {
  let currentFamilyId = null;
  if (currentRefreshToken) {
    const hash = crypto.createHash('sha256').update(String(currentRefreshToken)).digest('hex');
    const cur = await pool.query(
      'SELECT family_id FROM refresh_tokens WHERE user_id = $1 AND token_hash = $2', [userId, hash]);
    if (cur.rows[0]) currentFamilyId = cur.rows[0].family_id;
  }

  const { rows } = await pool.query(
    `SELECT rt.family_id,
            MIN(rt.created_at) AS started_at,
            MAX(rt.created_at) AS last_active_at,
            (SELECT r2.device_info FROM refresh_tokens r2
              WHERE r2.family_id = rt.family_id ORDER BY r2.created_at DESC LIMIT 1) AS device_info
       FROM refresh_tokens rt
      WHERE rt.user_id = $1
      GROUP BY rt.family_id
     HAVING bool_or(rt.revoked_at IS NULL AND rt.expires_at > NOW())
      ORDER BY MAX(rt.created_at) DESC`, [userId]);

  return rows.map((r) => ({
    id: r.family_id,
    deviceInfo: r.device_info,
    startedAt: r.started_at,
    lastActiveAt: r.last_active_at,
    isCurrent: r.family_id === currentFamilyId
  }));
}

async function revokeSession(userId, familyId) {
  const result = await pool.query(
    `UPDATE refresh_tokens SET revoked_at = NOW()
      WHERE user_id = $1 AND family_id = $2 AND revoked_at IS NULL`, [userId, familyId]);
  if (result.rowCount === 0) throw new AppError(404, 'Session not found', 'NOT_FOUND');
}

/** No email verification by product rule; the password re-check is the safeguard. */
async function changeEmail(userId, password, newEmail) {
  await verifyPassword(userId, password);
  const cur = await pool.query('SELECT email FROM users WHERE id = $1', [userId]);
  if (cur.rows[0] && String(cur.rows[0].email).toLowerCase() === newEmail) {
    throw new AppError(400, 'That is already your email', 'SAME_EMAIL');
  }
  try {
    await pool.query('UPDATE users SET email = $1 WHERE id = $2', [newEmail, userId]);
  } catch (err) {
    if (err.code === '23505') throw new AppError(409, 'Email or username already taken', 'CONFLICT');
    throw err;
  }
  return { email: newEmail };
}

/** Logging in again reactivates the account (see authService.login). */
async function deactivateAccount(userId, password) {
  await verifyPassword(userId, password);
  await withTransaction(async (client) => {
    await client.query("UPDATE users SET status = 'deactivated' WHERE id = $1", [userId]);
    await revokeEverywhere(client, userId);
  });
}

/** Anonymizes the account, frees the email/username, hides posts and revokes every session. */
async function deleteAccount(userId, password) {
  await verifyPassword(userId, password);
  // Unusable random password hash, computed before the transaction to keep it short.
  const unusableHash = await bcrypt.hash(crypto.randomBytes(48).toString('hex'), BCRYPT_COST);
  await withTransaction(async (client) => {
    await client.query(
      `UPDATE users SET status = 'deleted',
              email = 'deleted+' || id::text || '@levia.invalid',
              username = 'deleted_' || substr(replace(id::text, '-', ''), 1, 12),
              display_name = 'Deleted user', bio = NULL, avatar_url = NULL,
              password_hash = $2
        WHERE id = $1`, [userId, unusableHash]);
    await client.query('DELETE FROM password_reset_tokens WHERE user_id = $1', [userId]);
    await client.query('UPDATE posts SET deleted_at = NOW() WHERE author_id = $1 AND deleted_at IS NULL', [userId]);
    await revokeEverywhere(client, userId);
  });
}

module.exports = {
  verifyPassword, listSessions, revokeSession, changeEmail, deactivateAccount, deleteAccount
};
